insert into public.site_settings (id, school_name, project_name, green_school_goal) values (1, '16-maktab', 'EcoSchool16', '“Green School” respublika tanlovi umumta’lim maktablarida ekologik madaniyatni shakllantirish, Eco-Schools “7 qadam” metodologiyasini amalda qo‘llash va o‘quvchilarning ekologik tashabbuslarini qo‘llab-quvvatlashga qaratilgan.') on conflict (id) do nothing;
insert into public.stats (key, label, value, unit, sort_order) values ('students', 'Ekologik tadbirlarda qatnashgan o‘quvchilar', null, 'nafar', 1) on conflict (key) do nothing;
insert into public.stats (key, label, value, unit, sort_order) values ('plants', 'Ekilgan daraxt va gullar', null, 'tup', 2) on conflict (key) do nothing;
insert into public.stats (key, label, value, unit, sort_order) values ('waste', 'Yig‘ilgan chiqindilar', null, 'kg', 3) on conflict (key) do nothing;
insert into public.stats (key, label, value, unit, sort_order) values ('projects', 'Amalga oshirilgan ekologik loyihalar', null, 'ta', 4) on conflict (key) do nothing;
insert into public.steps (step_number, title, short_description, description, icon, status) values (1, 'Ekologik qo‘mita', 'Maktab ekologik jamoasini tashkil etish.', 'O‘quvchilar, o‘qituvchilar, maktab ma’muriyati, texnik xodimlar va ota-onalar vakillaridan iborat ekologik qo‘mita tuziladi. Qo‘mita dasturning barcha bosqichlarini boshqaradi, yig‘ilishlar o‘tkazadi va qarorlarni hujjatlashtiradi.', 'Users', 'planned') on conflict (step_number) do nothing;
insert into public.steps (step_number, title, short_description, description, icon, status) values (2, 'Ekologik tahlil', 'Maktabdagi ekologik holatni o‘rganish.', 'Chiqindilar, suv, energiya, maktab hududi, bioxilma-xillik va sog‘lom turmush tarzi kabi yo‘nalishlarda maktabning hozirgi holati o‘rganiladi. Tahlil natijalari keyingi harakat rejasi uchun asos bo‘ladi.', 'Search', 'planned') on conflict (step_number) do nothing;
insert into public.steps (step_number, title, short_description, description, icon, status) values (3, 'Harakat rejasi', 'Ekologik muammolar uchun yechimlar rejasini tuzish.', 'Ekologik tahlil asosida ustuvor yo‘nalishlar tanlanadi va har biri uchun aniq maqsad, mas’ul shaxslar, muddatlar hamda o‘lchanadigan ko‘rsatkichlar belgilanadi.', 'ClipboardList', 'planned') on conflict (step_number) do nothing;
insert into public.steps (step_number, title, short_description, description, icon, status) values (4, 'Monitoring va baholash', 'Natijalarni o‘lchash va tahlil qilish.', 'Harakat rejasining bajarilishi muntazam kuzatib boriladi: ko‘rsatkichlar o‘lchanadi, natijalar boshlang‘ich holat bilan solishtiriladi va kerak bo‘lsa reja yangilanadi.', 'LineChart', 'planned') on conflict (step_number) do nothing;
insert into public.steps (step_number, title, short_description, description, icon, status) values (5, 'O‘quv dasturiga integratsiya', 'Ekologik mavzularni ta’limga kiritish.', 'Ekologik mavzular turli fanlar darslariga, sinfdan tashqari mashg‘ulotlar va to‘garaklarga kiritiladi. O‘quvchilar amaliy tadqiqotlar orqali bilim oladi.', 'BookOpen', 'planned') on conflict (step_number) do nothing;
insert into public.steps (step_number, title, short_description, description, icon, status) values (6, 'Axborot va hamkorlik', 'O‘quvchilar, ota-onalar va jamoatchilikni jalb qilish.', 'Maktab ekologik faoliyati haqida axborot taxtalari, ijtimoiy tarmoqlar va tadbirlar orqali ma’lumot beriladi. Ota-onalar, mahalla va hamkor tashkilotlar jalb qilinadi.', 'Megaphone', 'planned') on conflict (step_number) do nothing;
insert into public.steps (step_number, title, short_description, description, icon, status) values (7, 'Ekologik kodeks', 'Maktabning ekologik qoidalarini ishlab chiqish.', 'Butun maktab jamoasi ishtirokida maktabning ekologik qadriyatlari va kundalik xatti-harakat qoidalarini ifodalovchi ekologik kodeks (shior) ishlab chiqiladi va ko‘zga ko‘rinadigan joyga joylashtiriladi.', 'ScrollText', 'planned') on conflict (step_number) do nothing;
